'use strict';

/**
 * Laberinto board screen (TRIOFSND-258): renders the maze a single round
 * carries (`round.maze`, as generated by `src/game/mazeGenerator.js` /
 * `src/game/mazeGame.js`'s `startRound`), four large directional controls,
 * and drives one round's movement to its goal.
 *
 * Movement/availability model: this screen never re-derives maze-solving
 * logic -- it only ever reads the current cell's own `walls` (the same
 * N/S/E/W model `mazeGenerator.js`/`mazeGame.js` already carve/validate) to
 * decide whether a direction is open, exactly mirroring `mazeGame.js`'s own
 * `isMoveBlocked`. That check runs both proactively (to disable/label a
 * blocked direction's button before it's even pressed, per this ticket's
 * "estados de disponibilidad") and reactively (on every move attempt, touch
 * or keyboard alike, before advancing the tracked position).
 *
 * Movement input: the four buttons handle touch/click; `root`'s own
 * `keydown` listener additionally maps the arrow keys to the same
 * `attemptMove`, so a keyboard-only player has full parity with touch
 * (no separate/duplicated move logic between the two input paths).
 *
 * Accessibility: a single `role="status"`/`aria-live="polite"` region
 * (`announcementEl`, `.sr-only`, same pattern as questionScreen.js's own
 * announcement node) carries every state change this ticket asks for --
 * round change, blocked movement, round result and end of game -- as one
 * coherent sentence per event, never simultaneous competing live regions.
 * The board itself is `role="img"` with a single descriptive
 * `strings.boardLabel`; per-cell detail (walls, dinosaur, food) is visual
 * only (`aria-hidden`), since the announcement region plus the controls'
 * own labels already cover every state change a screen reader needs.
 *
 * 375px width (constraint: "sin desplazamiento horizontal en todos los
 * niveles"): the board is a CSS grid sized from `round.maze.width/height`
 * via inline custom properties (`--maze-cols`/`--maze-rows`, set below) and
 * constrained to `min(100%, 320px)` in main.css, so a 9x9 (hardest level)
 * grid shrinks its cells instead of growing the board past the viewport --
 * no per-level sizing logic needed here.
 *
 * End of round vs. end of game: this screen only ever renders one round
 * (`round`), mirroring how questionScreen.js only ever renders one
 * question -- multi-round orchestration belongs to the caller (the app
 * shell), same as main.js's `renderQuestionAt` walks quiz questions forward.
 * `options.roundNumber`/`options.totalRounds` tell it whether the round
 * just finished was the game's last one: reaching the goal always shows the
 * round-result box, but the last round additionally shows the gameOver
 * heading/message instead of (just) the correctMessage, and the single
 * "Siguiente" button calls `options.onGameOver(score)` instead of
 * `options.onNext(score)` -- reaching the goal is always a success (no
 * "wrong" outcome in a maze), so the score shown/returned is simply
 * `options.score + 1`, never computed by re-deriving scoring rules here.
 *
 * Browser bridge: DinoQuiz has no bundler, so this screen -- which the
 * browser actually runs -- lives under `public/` and follows the dual
 * CommonJS/global pattern of public/scripts/questionScreen.js. It resolves
 * its i18n strings from `options.strings`, or `window.DinoQuiz.strings.maze`
 * in the browser, or the `src/i18n` loader under Node -- never a hardcoded
 * string (AC-15). It registers on `window.DinoQuiz.screens.renderMazeScreen`;
 * the canonical `src/screens/MazeScreen.js` re-exports this file.
 */

(function () {
  var DEFAULT_TOTAL_ROUNDS = 10;
  var DEFAULT_ROUND_NUMBER = 1;
  var DEFAULT_SCORE = 0;

  // Direction -> the wall (mazeGenerator.js's N/S/E/W model) and the
  // row/col step that direction takes once that wall is open. Kept as a
  // local, tiny lookup (not a require of mazeGame.js) since the browser has
  // no bundler to resolve that module's own dependency graph at runtime.
  var MOVE_DELTAS = {
    up: { wall: 'N', deltaRow: -1, deltaCol: 0 },
    down: { wall: 'S', deltaRow: 1, deltaCol: 0 },
    left: { wall: 'W', deltaRow: 0, deltaCol: -1 },
    right: { wall: 'E', deltaRow: 0, deltaCol: 1 },
  };
  var DIRECTIONS = ['up', 'down', 'left', 'right'];

  var WALL_CLASS = {
    N: 'maze-screen__cell--wall-top',
    S: 'maze-screen__cell--wall-bottom',
    E: 'maze-screen__cell--wall-right',
    W: 'maze-screen__cell--wall-left',
  };

  var FOOD_ICON = {
    carne: '🍖',
    hojas: '🌿',
    mixto: '🍽️',
  };
  var DEFAULT_FOOD_ICON = '🍽️';
  var DINOSAUR_ICON = '🦕';

  function resolveStrings(options) {
    options = options || {};
    if (options.strings) {
      return options.strings;
    }
    if (typeof require === 'function') {
      var i18n = require('../../src/i18n');
      return i18n.getStrings(options.locale || i18n.DEFAULT_LOCALE).maze;
    }
    var bundle = (typeof window !== 'undefined' && window.DinoQuiz && window.DinoQuiz.strings) || null;
    return bundle ? bundle.maze : null;
  }

  /** Fills "{key}" placeholders in `template` from `values`; unknown keys are left untouched. */
  function formatTemplate(template, values) {
    return Object.keys(values).reduce(function (result, key) {
      return result.split('{' + key + '}').join(values[key]);
    }, template);
  }

  /** Whether `direction` is blocked by a wall from `position` in `maze`'s grid (mirrors mazeGame.js's isMoveBlocked). */
  function isDirectionBlocked(maze, position, direction) {
    var cell = maze.grid[position.row][position.col];
    return Boolean(cell.walls[MOVE_DELTAS[direction].wall]);
  }

  function renderMazeScreen(container, round, options) {
    options = options || {};
    var strings = resolveStrings(options);
    var maze = round.maze;
    var roundNumber = options.roundNumber || DEFAULT_ROUND_NUMBER;
    var totalRounds = options.totalRounds || DEFAULT_TOTAL_ROUNDS;
    var isLastRound = roundNumber >= totalRounds;
    var scoreBeforeRound = typeof options.score === 'number' ? options.score : DEFAULT_SCORE;

    var position = { row: round.position.row, col: round.position.col };
    var moves = round.moves || 0;
    var finished = false;

    container.innerHTML = '';

    var root = document.createElement('div');
    root.className = 'maze-screen';

    var title = document.createElement('h2');
    title.className = 'maze-screen__title';
    title.textContent = strings.screenTitle;
    title.tabIndex = -1;

    var progressRow = document.createElement('div');
    progressRow.className = 'maze-screen__progress-row';

    var levelEl = null;
    if (typeof round.level === 'number') {
      levelEl = document.createElement('p');
      levelEl.className = 'maze-screen__level';
      levelEl.textContent = formatTemplate(strings.levelFormat, { level: round.level });
      progressRow.appendChild(levelEl);
    }

    var roundEl = document.createElement('p');
    roundEl.className = 'maze-screen__round';
    roundEl.textContent = formatTemplate(strings.roundFormat, { current: roundNumber, total: totalRounds });
    progressRow.appendChild(roundEl);

    var instructions = document.createElement('p');
    instructions.className = 'maze-screen__instructions';
    instructions.textContent = strings.instructions;

    var board = document.createElement('div');
    board.className = 'maze-screen__board';
    board.setAttribute('role', 'img');
    board.setAttribute('aria-label', strings.boardLabel);
    board.style.setProperty('--maze-cols', maze.width);
    board.style.setProperty('--maze-rows', maze.height);

    var cells = [];
    for (var row = 0; row < maze.height; row += 1) {
      var cellRow = [];
      for (var col = 0; col < maze.width; col += 1) {
        var cellData = maze.grid[row][col];
        var cellEl = document.createElement('div');
        cellEl.className = 'maze-screen__cell';
        cellEl.setAttribute('aria-hidden', 'true');
        Object.keys(WALL_CLASS).forEach(function (wall) {
          if (cellData.walls[wall]) {
            cellEl.classList.add(WALL_CLASS[wall]);
          }
        });

        if (row === maze.goal.row && col === maze.goal.col) {
          cellEl.classList.add('maze-screen__cell--goal');
          var foodIcon = document.createElement('span');
          foodIcon.className = 'maze-screen__food-icon';
          foodIcon.textContent = FOOD_ICON[round.food] || DEFAULT_FOOD_ICON;
          cellEl.appendChild(foodIcon);
        }

        board.appendChild(cellEl);
        cellRow.push(cellEl);
      }
      cells.push(cellRow);
    }

    var dinosaurIcon = document.createElement('span');
    dinosaurIcon.className = 'maze-screen__dinosaur-icon';
    dinosaurIcon.textContent = DINOSAUR_ICON;

    function renderDinosaurPosition() {
      cells.forEach(function (cellRow) {
        cellRow.forEach(function (cellEl) {
          cellEl.classList.remove('maze-screen__cell--dinosaur');
        });
      });
      var currentCell = cells[position.row][position.col];
      currentCell.classList.add('maze-screen__cell--dinosaur');
      currentCell.insertBefore(dinosaurIcon, currentCell.firstChild);
    }

    // Visible (not aria-hidden) legend for the board's two icons: the board
    // itself is a single-labeled role="img" with aria-hidden children (a
    // 9x9 grid isn't practical to narrate cell-by-cell), so this is where
    // `dinosaurAlt`/`foodAlt` actually reach the player -- as plain text a
    // non-reader can still match to the icon shape, and a screen reader
    // reads normally since it sits outside the aria-hidden board.
    var legend = document.createElement('div');
    legend.className = 'maze-screen__legend';

    var dinosaurLegendItem = document.createElement('p');
    dinosaurLegendItem.className = 'maze-screen__legend-item';
    dinosaurLegendItem.textContent = DINOSAUR_ICON + ' ' + strings.dinosaurAlt;

    var foodLegendItem = document.createElement('p');
    foodLegendItem.className = 'maze-screen__legend-item';
    foodLegendItem.textContent = (FOOD_ICON[round.food] || DEFAULT_FOOD_ICON) + ' ' + strings.foodAlt;

    legend.appendChild(dinosaurLegendItem);
    legend.appendChild(foodLegendItem);

    var blockedMessage = document.createElement('p');
    blockedMessage.className = 'maze-screen__blocked-message';

    var controlsGroup = document.createElement('div');
    controlsGroup.className = 'maze-screen__controls';
    controlsGroup.setAttribute('role', 'group');
    controlsGroup.setAttribute('aria-label', strings.controls.groupLabel);

    var buttons = {};
    var stateLabels = {};

    DIRECTIONS.forEach(function (direction) {
      var wrapper = document.createElement('div');
      wrapper.className = 'maze-screen__control maze-screen__control--' + direction;

      var button = document.createElement('button');
      button.type = 'button';
      button.className = 'maze-screen__control-button maze-screen__control-button--' + direction;
      button.textContent = strings.controls[direction];
      button.addEventListener('click', function () {
        attemptMove(direction);
      });

      var stateLabel = document.createElement('span');
      stateLabel.className = 'maze-screen__control-state';
      stateLabel.hidden = true;

      wrapper.appendChild(button);
      wrapper.appendChild(stateLabel);
      controlsGroup.appendChild(wrapper);

      buttons[direction] = button;
      stateLabels[direction] = stateLabel;
    });

    function updateControlsAvailability() {
      DIRECTIONS.forEach(function (direction) {
        var blocked = isDirectionBlocked(maze, position, direction);
        var button = buttons[direction];
        var stateLabel = stateLabels[direction];

        button.disabled = blocked;

        if (blocked) {
          button.setAttribute(
            'aria-label',
            formatTemplate(strings.controls.unavailableAriaLabelFormat, { direction: strings.controls[direction] })
          );
          stateLabel.textContent = strings.controls.unavailableState;
          stateLabel.hidden = false;
        } else {
          button.setAttribute('aria-label', strings.controls[direction + 'AriaLabel']);
          stateLabel.textContent = '';
          stateLabel.hidden = true;
        }
      });
    }

    var announcementEl = document.createElement('p');
    announcementEl.className = 'maze-screen__announcement sr-only';
    announcementEl.setAttribute('role', 'status');
    announcementEl.setAttribute('aria-live', 'polite');

    var resultBox = document.createElement('div');
    resultBox.className = 'maze-screen__result';
    resultBox.hidden = true;

    var resultHeading = document.createElement('h3');
    resultHeading.className = 'maze-screen__result-heading';
    resultHeading.hidden = true;

    var resultMessage = document.createElement('p');
    resultMessage.className = 'maze-screen__result-message';

    var nextButton = document.createElement('button');
    nextButton.type = 'button';
    nextButton.className = 'maze-screen__next-button';
    nextButton.textContent = strings.roundResult.nextButton;
    nextButton.hidden = true;

    resultBox.appendChild(resultHeading);
    resultBox.appendChild(resultMessage);

    var finalScore = scoreBeforeRound;

    function handleGoalReached() {
      finished = true;
      controlsGroup.hidden = true;
      finalScore = scoreBeforeRound + 1;

      if (isLastRound) {
        resultHeading.hidden = false;
        resultHeading.textContent = strings.gameOver.heading;
        resultMessage.textContent = strings.gameOver.message;
        announcementEl.textContent = formatTemplate(strings.gameOver.announcementFormat, {
          score: finalScore,
          total: totalRounds,
        });
      } else {
        resultHeading.hidden = true;
        resultMessage.textContent = strings.roundResult.correctMessage;
        announcementEl.textContent = formatTemplate(strings.roundResult.foodDeliveredAnnouncementFormat, { moves: moves });
      }

      resultBox.hidden = false;
      nextButton.hidden = false;
    }

    function attemptMove(direction) {
      if (finished) {
        return;
      }

      if (isDirectionBlocked(maze, position, direction)) {
        blockedMessage.textContent = strings.movementBlocked.message;
        announcementEl.textContent = strings.movementBlocked.announcement;

        if (typeof options.onMove === 'function') {
          options.onMove({ direction: direction, blocked: true, position: position, moves: moves });
        }
        return;
      }

      var delta = MOVE_DELTAS[direction];
      position = { row: position.row + delta.deltaRow, col: position.col + delta.deltaCol };
      moves += 1;
      blockedMessage.textContent = '';
      renderDinosaurPosition();
      updateControlsAvailability();

      var reachedGoal = position.row === maze.goal.row && position.col === maze.goal.col;

      if (typeof options.onMove === 'function') {
        options.onMove({ direction: direction, blocked: false, position: position, moves: moves, reachedGoal: reachedGoal });
      }

      if (reachedGoal) {
        handleGoalReached();
      }
    }

    nextButton.addEventListener('click', function () {
      if (isLastRound) {
        if (typeof options.onGameOver === 'function') {
          options.onGameOver(finalScore);
        }
      } else if (typeof options.onNext === 'function') {
        options.onNext(finalScore);
      }
    });

    var KEY_TO_DIRECTION = {
      ArrowUp: 'up',
      ArrowDown: 'down',
      ArrowLeft: 'left',
      ArrowRight: 'right',
    };

    root.addEventListener('keydown', function (event) {
      var direction = KEY_TO_DIRECTION[event.key];
      if (!direction) {
        return;
      }
      event.preventDefault();
      attemptMove(direction);
    });

    root.appendChild(title);
    root.appendChild(progressRow);
    root.appendChild(instructions);
    root.appendChild(board);
    root.appendChild(legend);
    root.appendChild(blockedMessage);
    root.appendChild(controlsGroup);
    root.appendChild(resultBox);
    root.appendChild(nextButton);
    root.appendChild(announcementEl);
    container.appendChild(root);

    renderDinosaurPosition();
    updateControlsAvailability();
    announcementEl.textContent = formatTemplate(strings.roundChangeAnnouncementFormat, {
      current: roundNumber,
      total: totalRounds,
    });

    // A real arrow-key press always targets `document.activeElement`, which
    // is `<body>` by default -- outside `root`'s subtree, so its `keydown`
    // listener above would never fire. Focusing `title` (same
    // tabIndex=-1 + .focus() pattern as modeSelectorScreen.js/
    // ageGateScreen.js's own screen-mount focus) puts an element inside
    // `root` in focus, giving keyboard parity with the on-screen buttons.
    if (typeof title.focus === 'function') {
      title.focus();
    }

    return {
      root: root,
      board: board,
      legend: legend,
      controlsGroup: controlsGroup,
      controlButtons: buttons,
      blockedMessage: blockedMessage,
      resultBox: resultBox,
      resultHeading: resultHeading,
      resultMessage: resultMessage,
      nextButton: nextButton,
      announcement: announcementEl,
      announcementEl: announcementEl,
      getPosition: function () {
        return position;
      },
      getMoves: function () {
        return moves;
      },
      isFinished: function () {
        return finished;
      },
    };
  }

  var api = {
    renderMazeScreen: renderMazeScreen,
  };

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = api;
  }

  if (typeof window !== 'undefined') {
    window.DinoQuiz = window.DinoQuiz || {};
    window.DinoQuiz.screens = window.DinoQuiz.screens || {};
    window.DinoQuiz.screens.renderMazeScreen = renderMazeScreen;
  }
})();
